                    // overshooting the next same-engine recovery's std-derived deadline.
                    let expiry =
                        tokio::time::Instant::from_std(Instant::now() + Duration::from_secs(60));
                    tokio::time::advance(expiry.duration_since(tokio::time::Instant::now())).await;
